def lire_csv_texte(chemin, sep=";", encodage="utf-8"):
    """Toutes les colonnes en texte : rien n'est converti."""
    if not chemin.exists():
        raise ErreurSource(f"source absente : {chemin}")
    return pd.read_csv(chemin, sep=sep, dtype=str,
                       keep_default_na=False, encoding=encodage)

