class Entrepot:
    """Accès à outputs/entrepot.sqlite : with Entrepot(chemin) as e:"""
    def __enter__(self):
        self.con = sqlite3.connect(self.chemin)
        self.con.execute("PRAGMA foreign_keys = ON")
        return self

    def __exit__(self, typ, val, tb):
        if typ is None:
            self.con.commit()      # tout s'est bien passé : on valide
        else:
            self.con.rollback()    # une erreur : on annule tout

